TRANSLATIONS_SLICE3 = {
    # ==================== STm10001_07 (109 items) ====================
    'STm10001_07.4': 'Hồi Bảy',
    'STm10001_07.5': 'Thường Nhật Của Vệ Dạ Giả',
    'STm10001_07.6': 'Alina che chở cho một cô bé bị đám đông giận dữ cáo buộc là Thánh Nữ Sa Ngã. Thân phận Thị Giả của bạn đã giúp cô ấy thoát khỏi vòng vây, và để giành được lòng tin của cô ấy, bạn cùng Elis đã gia nhập Đội Vệ Dạ.',
    'STm10001_07.29': 'Tháng Thứ Năm',
    'STm10001_07.31': 'Đảo Filanis',
    'STm10001_07.32': 'Đại Lộ Trung Tâm',
    'STm10001_07.50': 'Mọi người nhìn cô bé xem. Con bé nào phải Thánh Nữ Sa Ngã đâu. Nó chỉ là một đứa trẻ đáng thương, ngay cả một phép thuật cỏn con cũng chẳng biết niệm.',
    'STm10001_07.75': 'Cư Dân Filanis Kích Động',
    'STm10001_07.76': 'Ở Filanis làm gì có người như thế!==W== Đây chỉ là mánh khóe lừa bịp thôi! Ả nhất định là Thánh Nữ Sa Ngã cải trang!',
    'STm10001_07.81': 'Nếu các người không tin tôi, tôi sẽ đưa con bé đến diện kiến Đại Tế Ty. Hãy để ngài ấy định đoạt.',
    'STm10001_07.84': 'Cư Dân Filanis Giận Dữ',
    'STm10001_07.85': 'Hừ. Hễ gặp chuyện khó khăn là lại núp sau lưng Đại Tế Ty. Làm Vệ Dạ Giả sướng thật đấy nhỉ.',
    'STm10001_07.86': 'Con tôi đã mất tích cả tháng trời nay rồi! Còn đám Vệ Dạ Giả vô dụng các người thì chẳng làm nên tích sự gì cả!',
    'STm10001_07.89': 'Chúng tôi vất vả lắm mới bắt được kẻ tình nghi, vậy mà cô không trừng trị ả, lại còn ra mặt che chở! Sao nào, cô là đồng phạm của ả đấy à?!',
    'STm10001_07.92': 'Cư Dân Filanis Hung Hãn',
    'STm10001_07.93': 'Ném ả vào nhà tắm đi! Nước thần sẽ sớm vạch trần chân tướng của ả thôi.',
    'STm10001_07.96': 'Đúng đấy! Kiểm tra ả ngay bây giờ đi!',
    'STm10001_07.99': 'Hãy nhìn xem cô bé yếu ớt thế nào kìa. Ném con bé vào làn nước đó chẳng khác nào dồn con bé vào chỗ chết!',
    'STm10001_07.101': 'Lấy danh dự của một Vệ Dạ Giả, tôi thề sẽ thẩm vấn và đem lại câu trả lời rõ ràng cho mọi người.==W== Nhưng hiện tại, cô bé cần một y sĩ. Xin hãy tránh đường.',
    'STm10001_07.131': 'Cô Bé Bị Thương',
    'STm10001_07.132': '<size=30>Ư... Đau quá...</size>==W==',
    'STm10001_07.141': 'Có mơ đi! Cô phải tra hỏi ả ngay tại đây.',
    'STm10001_07.142': 'Đúng vậy, ngay tại đây, ngay lúc này!',
    'STm10001_07.144': '(Có điều gì đó không ổn...==W== Sao mọi người lại kích động đến mức này?==W== Thôi bỏ đi...==W== Mình phải đưa đứa trẻ này thoát khỏi đây trước đã.)',
    'STm10001_07.145': 'Lùi lại. Các người đang cản trở người thi hành công vụ đấy. Nếu cần thiết, tôi sẽ dùng vũ lực để mở đường.',
    'STm10001_07.147': 'Dùng vũ lực sao?==W== Hừ. Cô là Hiệp Sĩ, nhưng tôi cũng từng là chiến binh đấy.==W== Và tôi cũng biết vung kiếm chứ chẳng đùa đâu.',
    'STm10001_07.162': 'Cư Dân Filanis Quá Khích',
    'STm10001_07.163': 'Nói chuẩn lắm! Chúng ta sinh ra và lớn lên ở Filanis, từng đổ máu nơi chiến trường! Không đời nào chúng ta để một kẻ ngoại lai thích làm gì thì làm. Cho cô ta thấy ai mới là chủ đất này!',
    'STm10001_07.166': 'Cư Dân Filanis Đứng Xem',
    'STm10001_07.167': 'Đúng đấy! Cho cô ta biết tay đi!',
    'STm10001_07.173': 'Sao nào?==W== Nếu thực sự muốn đưa cô gái đó đi, ngươi phải bước qua xác ta trước đã. Để xem ngươi có thực sự <size=50>xứng đáng với danh hiệu đó</size> không.',
    'STm10001_07.178': '(Mình phải làm sao đây? Đường kiếm của họ đầy sơ hở.==W== Mình có thể dễ dàng đột phá vòng vây, nhưng không thể tránh khỏi việc làm ai đó bị thương.)',
    'STm10001_07.181': '(Trách nhiệm của mình là bảo vệ người dân Filanis, chứ không phải làm hại họ.==W== Nhưng nếu cứ chần chừ ở đây...==W== Cô bé này sẽ...)',
    'STm10001_07.190': 'Chuyện gì đang diễn ra ở đây thế này?==W== Tránh đường mau! Các ngươi đang chắn lối đi của ngài Thị Giả đấy!',
    'STm10001_07.195': 'Thị Giả sao?==W== Từ khi nào mà Filanis chúng ta lại có Thị Giả thế?',
    'STm10001_07.196': 'Nghe nói có một Thị Giả phương xa vừa tới thành phố. Nghe đâu Đại Tế Ty Coppelius tiếp đãi ==SEX4== như thượng khách vậy.==W== Kìa, chắc chắn đó là ==SEX4== rồi.',
    'STm10001_07.207': 'Hừm...==W== Khí chất xuất chúng thế kia,==W== y phục lộng lẫy chưa từng thấy bao giờ...==W== Đúng là một quý nhân mà chúng ta tuyệt đối không nên đắc tội.',
    'STm10001_07.217': 'Có chuyện gì ồn ào ở đây vậy? Rốt cuộc sự tình là thế nào?',
    'STm10001_07.221': 'Kính thưa ngài Thị Giả! Chúng tôi không cố ý cản trở đường đi của ngài.==W== Chỉ là... Chúng tôi vừa bắt được Thánh Nữ Sa Ngã! Nhưng cô Vệ Dạ Giả này lại từ chối thực thi công lý.==W== Cô ta đang tìm cách lén lút đưa phạm nhân đi!',
    'STm10001_07.226': 'Ồ? Hóa ra là Alina.==W== Thật khéo khi lại tình cờ gặp cô ở đây.',
    'STm10001_07.228': 'Chào buổi sáng, ==SEX12== Thị Giả.==W== Tôi xin nhận hoàn toàn trách nhiệm cho sơ suất vừa rồi của mình.==W== Sau khi đưa đứa trẻ này đến chỗ y sĩ, tôi sẽ tự mình đến chịu phạt.',
    'STm10001_07.230': 'Thế sao được hả Alina? Cô không nghe những người dân lương thiện này nói gì sao?==W== Họ đang yêu cầu xử lý kẻ tình nghi này đấy. Cô không thể cứ thế phớt lờ họ mà đưa con bé đi trị thương được.',
    'STm10001_07.233': 'Nhưng thưa Thị Giả, đứa trẻ này không phải...',
    'STm10001_07.236': 'Không nhưng nhị gì cả.==W== Ta dẫu chỉ là một Thị Giả phương xa không nên can thiệp vào nội bộ, nhưng là một Vệ Dạ Giả của Filanis, bổn phận của cô là phải lắng nghe tiếng nói của bách tính.',
    'STm10001_07.239': 'Ngài nói quá chuẩn xác! Đúng phong thái của một bậc tôn quý! Cuối cùng cũng có một người đứng đầu thấu hiểu nỗi lòng của chúng tôi.',
    'STm10001_07.242': 'Chẳng bù cho ai kia, thà che chở cho kẻ tình nghi còn hơn làm đúng phận sự của mình!',
    'STm10001_07.243': 'Này! Cô nghe rõ lời ngài Thị Giả rồi chứ. Tuân lệnh đi, Vệ Dạ Giả!',
    'STm10001_07.244': 'Tôi...==W== Tôi hiểu rồi. ==SEX12== Thị Giả, xin cứ ra lệnh. Tôi sẽ làm theo ý ngài.',
    'STm10001_07.246': 'Đã giao phó quyết định này cho ta, vậy thì ta đành nhận lời vậy.',
    'STm10001_07.247': 'Alina, hãy áp giải cô gái này về phòng nghỉ của ta. Ta sẽ đích thân thẩm vấn cô ta.',
    'STm10001_07.253': 'Bên Ngoài Đảo Filanis',
    'STm10001_07.254': 'Căn Hộ Cũ Nát',
    'STm10001_07.257': 'Kiểm tra xong rồi. Tin xấu là cả thể xác lẫn tinh thần của con bé đều bị tổn thương nghiêm trọng.',
    'STm10001_07.265': 'Tình trạng suy kiệt kéo dài cùng chấn thương nặng nề đã khiến tâm trí con bé suy sụp.==W== Hơn nữa, có ai đó đã dùng ma pháp can thiệp vào ký ức của con bé.==W== Hiện tại không thể nào tra hỏi được thông tin hữu ích gì đâu.',
    'STm10001_07.274': '<size=50>Nghiêm trọng... đến mức đó sao?!</size>==W== Lũ người tàn nhẫn kia thật đáng bị trừng phạt!==W== C-Cô bé có thể bình phục lại không?==W==',
    'STm10001_07.276': 'Chà chà.==W== Xem ai đang lo lắng sốt sắng cho một kẻ xa lạ kìa.',
    'STm10001_07.279': 'Tôi...==W== Tôi xin lỗi. Ở nhà tắm lúc trước tôi đã lỡ lời. Tôi thực sự không có ý đó đâu.',
    'STm10001_07.280': 'Hừ, không cần xin lỗi đâu.==W== Trông tôi giống người hay để bụng lắm à?==W== Thôi yên tâm đi. Đó mới là tin xấu, còn đây là tin tốt này.',
    'STm10001_07.285': 'Con bé gặp nhiều vấn đề thật đấy, nhưng không có vết thương nào nguy hiểm đến tính mạng cả.==W== Cơ thể chỉ cần được nghỉ ngơi tẩm bổ thôi. Khi thể lực hồi phục, tổn thương ký ức do ma pháp sẽ tự khắc tiêu tan.',
    'STm10001_07.288': 'Đây, tôi đã kê một đơn thuốc bồi bổ rồi. Cứ chăm sóc con bé theo đúng thế này trong hai tuần, nó sẽ khỏe mạnh lại như thường.',
    'STm10001_07.289': 'Bắp cải, mật ong, thịt gà, nước mắm, quả sung, chà là, đậu gà...==W== Khoan đã, đây chỉ là danh sách đi chợ thôi mà.',
    'STm10001_07.290': 'Chính xác là vậy đấy. Khỏi cần thảo dược cầu kỳ làm gì. Thứ mà cô bé này thực sự cần nhất lúc này là một bữa ăn thịnh soạn.',
    'STm10001_07.291': 'Đã rõ!==W== Tôi đi lo ngay đây!',
    'STm10001_07.295': 'Phù.==W== Sư phụ, chúng ta đưa con bé vào phòng ngủ để nó nghỉ ngơi đi.==W== Cô đằng kia, Vệ Dạ Giả,==W== mau lại giúp một tay nào.==W==',
    'STm10001_07.309': 'Alina nhường lại phòng ngủ của chính mình cho cô bé. Khi chúng tôi đắp chăn lại, con bé vẫn nhìn vô định vào khoảng không, miệng lẩm bẩm cầu xin tha mạng. Dẫu vậy...==W== Nỗi sợ hãi tột cùng trên gương mặt con bé đã bắt đầu dịu bớt.',
    'STm10001_07.315': 'Thế giới này tàn nhẫn hơn tôi tưởng nhiều. Elis và Alina có lẽ chỉ là những ngoại lệ hiếm hoi. Những gì diễn ra ngày hôm nay...==W== Mới là hiện thực trần trụi đối với những số phận khốn cùng khác.',
    'STm10001_07.321': 'Cảm ơn ngài đã ra tay tương trợ, Thị Giả. Nếu không có ngài...==W== Tôi và cô bé đó chắc chắn đã bị vây khốn trên đảo rồi. Khéo lại phải phiền đến Đại Tế Ty Coppelius đứng ra giải vây mất.',
    'STm10001_07.324': 'Đừng bận tâm. Tôi cũng chưa làm được gì nhiều đâu.==W== Chỉ là tiện tay mượn chút oai phong và lợi dụng sự thiếu hiểu biết của họ thôi.',
    'STm10001_07.326': 'May mà bọn họ không biết tôi đang ở cùng chỗ với cô. Việc tôi bảo đưa con bé về đây để "thẩm vấn" cũng chẳng khác gì cô đưa con bé về điều trị cả.',
    'STm10001_07.327': 'Cô có nghĩ bọn họ sẽ phát hiện ra không? Một đám đông phẫn nộ kéo đến tận nhà cô là điều cuối cùng chúng ta mong muốn đấy.',
    'STm10001_07.328': 'Xin ngài cứ yên tâm, những người đó hiếm khi bước chân ra khỏi đảo. Họ hoàn toàn không biết những gì diễn ra ở ngoài này đâu.',
    'STm10001_07.329': 'Vậy thì tốt. Chúng ta có thể yên tâm tập trung chữa trị cho cô bé rồi.',
    'STm10001_07.331': 'Nhân tiện nhắc đến chuyện đó,==W== tại sao họ lại đinh ninh cô bé chính là Thánh Nữ Sa Ngã thế?==W== Tôi tưởng Filanis không có những thân phận bị giam cầm chứ.',
    'STm10001_07.333': 'Tôi sẽ giải thích cặn kẽ mọi chuyện ngay đây.==W== Nhưng trước đó...==W==',
    'STm10001_07.336': '==SEX12== Thị Giả, tôi đã phạm phải sai lầm nghiêm trọng khi vu khống Elis và nhốt cả hai người vào xe tù.==W== Tôi đã sẵn sàng nhận hình phạt.',
    'STm10001_07.339': 'À,==W== đây hẳn là chuyện mà lúc trước Elis đã nói với mình...==W==',
    'STm10001_07.344': 'Alina còn phải xin lỗi và đáp ứng bất kỳ yêu cầu nào của chúng ta, miễn là chúng không "gây ra cái chết hoặc để lại thương tật vĩnh viễn".==W== Ồ,==W== và họ suýt chút nữa đã trục xuất cô ấy khỏi Filanis đấy.',
    'STm10001_07.346': 'Tôi thực sự không muốn phạt cô ấy đâu.==W== Chẳng cần thiết phải làm thế.==W== Huống hồ,==W== Alina cũng chỉ đang làm tròn phận sự của mình thôi.',
    'STm10001_07.347': 'Đứng từ góc nhìn của một người ngoài cuộc,==W== thì tôi và Elis quả thật trông vô cùng khả nghi.',
    'STm10001_07.356': 'Suỵt. Sư phụ, sư phụ à.==W== Lại đây một chút đi.',
    'STm10001_07.364': 'Elis thấy thế nào? Chúng mình thật sự không cần phải làm khó Alina vì chuyện này đâu. Lúc nãy cậu còn lên tiếng bênh vực cô ấy cơ mà.',
    'STm10001_07.367': 'Đúng là thế,==W== nhưng cậu không thể cứ xua tay cho qua mà chẳng đòi hỏi gì được. Như vậy sẽ làm lộ sơ hở đấy.',
    'STm10001_07.368': 'Hơn nữa, đây là cơ hội hoàn hảo để kéo Alina về phe chúng ta.',
    'STm10001_07.369': 'Kéo cô ấy về phe chúng ta ư?',
    'STm10001_07.370': 'Phải đấy! Cậu nghĩ xem, ưu tiên hàng đầu của chúng ta lúc này là gì nào?',
    'STm10001_07.371': 'Là có được một thân phận vững chắc. Một vỏ bọc có thể đứng vững trước mọi sự soi xét.',
    'STm10001_07.372': 'Chính xác! Lời giải thích của chúng ta đã qua mắt được Thánh Nữ và Đại Tế Ty. Nhân tố bất định duy nhất còn lại chính là cô nàng Vệ Dạ Giả này.',
    'STm10001_07.373': 'Trên đường đến Filanis... Lời kể của chúng ta lộ ra không ít lỗ hổng. Nếu cô ấy bắt đầu đào sâu điều tra...',
    'STm10001_07.374': 'Nói cũng có lý. Vậy kế hoạch của cậu là gì?',
    'STm10001_07.376': 'Hì hì. Tính tình cô ấy cứng nhắc quá mức. Ngoại trừ Lulu ra, tôi đồ rằng trên đời này cô ấy chẳng có lấy một người bạn.',
    'STm10001_07.377': 'Những người như cô ấy giống như tượng đá cẩm thạch vậy. Mua chuộc hay đe dọa đều vô dụng cả.==W== Nếu muốn cô ấy ngả về phía chúng ta,==W== trước hết phải khiến cô ấy buông lỏng cảnh giác đã.',
    'STm10001_07.383': 'Buông lỏng cảnh giác?',
    'STm10001_07.384': 'Ý tôi là khiến cô ấy thả lỏng hơn. Chỉ cần làm cô ấy chịu bộc bạch điều mình mong muốn, chúng ta có thể giúp cô ấy đạt được nó.',
    'STm10001_07.385': 'Hừm...==W== Tôi hiểu rồi.',
    'STm10001_07.387': 'Nếu cậu chê cách đó quá chậm, tôi có nghiên cứu ra một phép khế ước ràng buộc hành động của người ký kết đấy.==W== Cậu có thể nhân cơ hội này giúp tôi thử nghiệm xem sao...==W==',
    'STm10001_07.393': '<size=52>Này! Cậu đi đâu đấy hả?!==W== Chúng mình còn chưa bàn xong chi tiết mà!</size>',
    'STm10001_07.396': 'Alina, tôi đã nghĩ ra hình phạt dành cho cô rồi.',
    'STm10001_07.398': 'Xin ngài cứ nói, tôi sẽ dốc hết sức để bù đắp cho hai người.',
    'STm10001_07.399': 'Hãy để chúng tôi gia nhập Đội Vệ Dạ và cùng đi tuần tra với cô.==W== Ngoài ra, hãy đối xử với tôi và Elis như những người ngang hàng, chứ không phải bề trên.==W== Bỏ hết mấy nghi thức rườm rà đi.',
    'STm10001_07.400': 'Rõ. Tôi sẽ...==W== Khoan đã,==W== ==SEX12== Thị Giả, ngài vừa nói gì cơ?',
    'STm10001_07.403': 'Cứ gọi ta là "==SEX12==" là vi phạm thỏa thuận đấy. Cứ gọi ta là ==PLAYER_NAME==, và gọi cô ấy là Elis.',
    'STm10001_07.405': '<size=52>Sư phụ?!</size>',
    'STm10001_07.406': 'Và cô cũng đừng gọi tôi là "Sư phụ" nữa. Chúng ta cần phải hòa nhập. Đã đến lúc tôi trả lại tự do hoàn toàn cho người đồng hành của mình rồi.',
    'STm10001_07.407': 'Chúng ta không có giấy tờ giao kèo nào ở đây cả, vậy nên hãy để Alina làm người làm chứng luôn nhé.',
    'STm10001_07.408': 'Tôi...==W== tôi hiểu rồi.==W== Tôi sẽ làm chứng cho việc ==PLAYER_NAME== trao trả tự do cho Elis.',
    'STm10001_07.409': 'Hầy...==W== Tôi thật sự không hiểu nổi cậu.==W== Rốt cuộc trong đầu cậu đang toan tính điều gì thế không biết?',
    'STm10001_07.410': 'Tốt lắm. Không ai phải dùng đến danh xưng câu nệ nữa, tôi thích thế này hơn đấy.==W== Nào...==W== Đội trưởng Alina, xin mời ra lệnh.',
    'STm10001_07.412': 'Là những tân binh mới nhất của Đội Vệ Dạ, bước đi đầu tiên của chúng ta là gì đây?',
    'STm10001_07.413': 'Vậy thì...==W== Chúng ta hãy cùng thảo luận về mối liên hệ giữa tin đồn Thánh Nữ Sa Ngã và các vụ mất tích gần đây tại Filanis.',

    # ==================== STm10001_08 (112 items) ====================
    'STm10001_08.4': 'Hồi Tám',
    'STm10001_08.5': 'Lời Nguyện Cầu Cấm Kỵ',
    'STm10001_08.6': 'Nhiều đứa trẻ liên tiếp mất tích khắp Filanis, khiến dư luận đổ mọi tội lỗi lên đầu Thánh Nữ Sa Ngã. Alina đã trút bỏ mối hoài nghi về bạn và Elis, đồng thời tiết lộ lý do vì sao cô ấy lại khao khát tìm hiểu về ma pháp phục sinh đến vậy.',
    'STm10001_08.24': 'Tháng Thứ Năm',
    'STm10001_08.26': 'Ngoài Khơi Filanis',
    'STm10001_08.27': 'Căn Hộ Cũ Nát',
    'STm10001_08.40': 'Dưới sự cai quản của Chấp Chính Quan Olympia, Filanis từ lâu đã là một thành bang hòa bình và trật tự. Người dân nơi đây sống trong cảnh an cư lạc nghiệp, những tội ác nghiêm trọng hầu như chẳng bao giờ xảy ra.',
    'STm10001_08.44': 'Trong suốt nhiều năm, Đội Vệ Dạ chúng tôi hiếm khi có việc gì nặng nhọc ngoài việc bắt trộm, dập tắt vài đám cháy nhỏ và xua đuổi lũ quái vật lảng vảng quá gần thành phố.',
    'STm10001_08.48': 'Thế nhưng một tháng trước, sự yên bình ấy đã tan thành mây khói.==W== Một bé gái bất ngờ mất tích ngay tại nhà mình,==W== và dẫu cho gia đình cùng tôi đã lùng sục khắp nơi, chúng tôi vẫn không tìm thấy một dấu vết nào.',
    'STm10001_08.64': 'Ban đầu, tôi còn ngỡ con bé trượt chân ngã xuống nước và bị dòng thủy triều cuốn ra khỏi Filanis.==W== Thế nhưng rồi...==W==',
    'STm10001_08.73': 'Một tuần sau, đứa trẻ thứ hai tiếp tục biến mất,==W== lần này là ở ngoại ô Filanis.==W== Theo lời gia đình, đứa bé chỉ ra ngoài mua ổ bánh mì rồi chẳng bao giờ quay trở lại nữa.',
    'STm10001_08.77': 'Mọi đứa trẻ ở Filanis đều biết bơi từ nhỏ, vậy nên khả năng hai đứa liên tiếp vô tình trượt chân ngã xuống nước là quá đỗi thấp. Lulu và tôi đã lục soát từng căn hầm, từng ngôi nhà hoang phế ở Filanis, nhưng đều trắng tay.',
    'STm10001_08.83': 'Bắt cóc ư? Nhưng chẳng hề có ai gửi thư đòi tiền chuộc. Liệu có phải là nạn buôn người không?',
    'STm10001_08.86': 'Tôi cũng từng nghĩ đến khả năng đó, nên đã mở rộng phạm vi tìm kiếm và giám sát chặt chẽ những lữ khách ngoại bang. Cùng khoảng thời gian đó, những tin đồn về Thánh Nữ Sa Ngã bắt đầu lan truyền khắp nơi.',
    'STm10001_08.91': 'Rất nhiều người đinh ninh rằng Thánh Nữ Sa Ngã đã lẻn vào Filanis==W== và bắt cóc những đứa trẻ tội nghiệp ấy đi để ăn thịt.',
    'STm10001_08.103': 'Thôi đi mà, ==W==dù cho Thánh Nữ Sa Ngã có độc ác đến đâu đi chăng nữa,==W== cô ấy cũng đâu thể nào ăn thịt trẻ con được chứ!',
    'STm10001_08.106': 'Tất nhiên rồi, đó là một lời đồn vô căn cứ đến nực cười. Trên thực tế...==W== tôi không tin Thánh Nữ Sa Ngã là kẻ chịu trách nhiệm cho những tội ác đó,==W== hay bất kỳ cái chết nào trong số ấy.',
    'STm10001_08.111': 'Hửm? Sao cô lại nghĩ như vậy?',
    'STm10001_08.113': 'Nếu cô ấy thực sự đang chạy trốn, thì việc di chuyển liên tục từ thành bang này sang thành bang khác là hạ sách tồi tệ nhất. Chẳng thà ẩn náu ở một nơi hẻo lánh nào đó và đợi cho đến khi thiên hạ lãng quên mình còn hơn.',
    'STm10001_08.115': 'Một Thánh Nữ có thể thoát khỏi nghi lễ tế thần thì không thể là kẻ ngu ngốc. Tôi không nghĩ cô ấy lại hành động dại dột đến mức sát hại người khác để che giấu thân phận, để rồi tự biến mình thành mục tiêu bị săn đuổi.',
    'STm10001_08.118': 'Thế nhưng... những thảm kịch ấy quả thật đã xảy ra...',
    'STm10001_08.125': 'Tôi từng đọc về một vụ án tương tự trong thư viện của Filanis.',
    'STm10001_08.126': 'Một kẻ thủ ác hàng loạt bị quy trách nhiệm cho ba mươi mạng người, nhưng trên thực tế gã ta chỉ ra tay trong năm vụ. Hai mươi lăm vụ còn lại đều là những kẻ bắt chước gây ra, rồi đổ vấy tội lỗi lên đầu kẻ thủ ác chưa rõ danh tính kia.',
    'STm10001_08.129': 'Ý cô là... Thánh Nữ Sa Ngã đã bị kẻ khác đổ tội oan.==W== Vậy thì tại sao lúc ở trong rừng, cô lại lấy cái danh đó ra để bắt giữ Elis?==W==',
    'STm10001_08.133': 'Cái danh gọi là Thánh Nữ Sa Ngã ấy khéo còn chẳng hề tồn tại trên đời. Đó có thể chỉ là một cái tên do người ta thêu dệt nên theo những lời đồn thổi thất thiệt.',
    'STm10001_08.134': 'Thế nhưng những kẻ tội phạm mượn cái danh xưng ấy để làm bình phong cho đủ loại tội ác tày trời... Bọn chúng lại hoàn toàn có thật.',
    'STm10001_08.139': 'Vài ngày trước đó.',
    'STm10001_08.151': 'Đội trưởng Alina,==W== lại có thêm một đứa trẻ nữa mất tích rồi.',
    'STm10001_08.153': 'Lại thêm một đứa nữa sao? Đây đã là đứa thứ ba rồi đấy...==W== Lulu,==W== em đã tra ra được chút manh mối nào về tin đồn Thánh Nữ Sa Ngã chưa?',
    'STm10001_08.155': 'Dạ, nếu bảo là manh mối thì...==W== Ngày hôm qua có một người đàn ông lạ mặt xuất hiện ở khu nhà tắm công cộng.',
    'STm10001_08.156': 'Người đàn ông lạ mặt ư?',
    'STm10001_08.163': 'Một lữ khách lắm tiền nhiều của. Nghe đồn hắn ta còn mang tước hiệu Hiệp Sĩ nữa kia.==W== Nhưng ánh mắt hắn cứ nhìn chòng chọc vào hàm răng và làn da của người khác, săm soi đánh giá...==W== Giống hệt như đang ngắm nghía hàng hóa vậy.',
    'STm10001_08.167': 'Thói quen đó... Đừng nói với chị hắn ta là một kẻ buôn người đấy nhé?',
    'STm10001_08.170': 'Hắn đi khắp khu nhà tắm kể cho mọi người nghe những câu chuyện về Thánh Nữ Sa Ngã. Nhưng rõ ràng hắn chỉ là kẻ từ nơi khác đến...==W== Làm sao hắn lại nắm rõ những tin đồn địa phương của chúng ta đến thế?',
    'STm10001_08.172': 'Rất đáng ngờ. Khả năng cao hắn chính là kẻ đã bắt cóc những đứa trẻ. Tôi nghe nói ở một số thành bang xa xôi, giới quý tộc không chuộng những người hầu tầm thường. Họ chỉ thích những kẻ bị bắt cóc, đặc biệt là những người từng xuất thân từ những gia đình danh giá.',
    'STm10001_08.175': 'Lulu, chúng ta mau đi tìm hắn thôi!',
    'STm10001_08.185': 'Đứng lại đó. Tôi là Alina thuộc Đội Vệ Dạ Filanis. Yêu cầu kiểm tra cỗ xe của các người.',
    'STm10001_08.191': 'Kẻ Buôn Nô Lệ',
    'STm10001_08.192': 'Hah, Filanis các người quả thực rất thích can thiệp bao đồng đấy nhỉ.==W== Bây giờ chúng ta đang ở nơi hoang dã, chứ đâu còn nằm trong thành phố của các người nữa.',
    'STm10001_08.197': 'Đội trưởng Alina, mấy cỗ xe kia...==W== Không, đó là những chiếc lồng sắt. Có vài người đang bị nhốt bên trong.',
    'STm10001_08.209': 'Hah. Chúng tao chưa từng đưa người vào Filanis, nên chẳng hề vi phạm bất kỳ luật lệ nào của Chấp Chính Quan Olympia cả.==W== Khoan đã. Trông mày quen mắt lắm.==W== À, mày là con nhỏ ở nhà tắm công cộng!',
    'STm10001_08.213': 'Dù xảy ra ở bất cứ nơi đâu, việc coi con người như món đồ chơi hay hàng hóa mua bán đều là tội ác ghê tởm. Hơn nữa các người còn bị tình nghi bắt cóc và gieo rắc hoang mang. Tôi muốn đưa các người về quy án.',
    'STm10001_08.214': 'Thật nực cười. Chỉ có hai đứa con gái ranh mà cũng đòi áp giải bọn tao về sao?==W== Tụi bây, xem ra chuyến này cỗ xe của chúng ta lại có thêm hai món hàng thượng hạng rồi. Rút vũ khí ra!',
    'STm10001_08.227': 'Biết điều một chút đi!==W== Lulu, giữ mạng sống cho chúng. Chúng ta vẫn cần bọn chúng khai ra tung tích của những đứa trẻ.',
    'STm10001_08.229': 'Rõ, thưa Đội trưởng.',
    'STm10001_08.233': 'Chúng tôi đã đánh bại toán buôn người, nhưng những đứa trẻ mất tích lại không nằm trong số những người bị nhốt trong lồng sắt.',
    'STm10001_08.234': 'Trên đường đi của chúng có một tòa tháp nằm sâu trong rừng. Tôi lo sợ bọn chúng có thể đã giấu những đứa trẻ bị bắt cóc ở đó, nên đã bảo Lulu quay về thành phố báo tin, còn tôi tự mình đánh một cỗ xe tù hướng về phía tòa tháp...==W== Và chính tại nơi đó, tôi đã chạm trán hai người.',
    'STm10001_08.239': 'Hóa ra sự tình là như thế. Cô vừa mới triệt phá một toán buôn người, và bọn chúng thì đang rêu rao tin đồn về Thánh Nữ Sa Ngã. Rồi cô bắt gặp tôi, với diện mạo y hệt như bức chân dung truy nã, bảo sao cô không nghi ngờ cho được. Hoàn toàn dễ hiểu thôi.',
    'STm10001_08.241': 'Thực ra... tôi chưa từng thực sự nghĩ cô là Thánh Nữ Sa Ngã. Thứ nhất, ánh mắt cô không phải là ánh mắt của kẻ từng nhuốm máu sát sinh. Và thứ hai, tôi luôn tin rằng Thánh Nữ Sa Ngã chỉ là một hình tượng bị thêu dệt quá đà qua những lời đồn đại.',
    'STm10001_08.243': 'Tôi nói vậy cốt là để xem phản ứng của cô ra sao thôi...==W== Một chút mẹo nhỏ mà Đội Vệ Dạ chúng tôi thường áp dụng khi thẩm vấn bọn trộm cắp: bắt đầu bằng một cáo buộc thật nghiêm trọng để xem chúng có dao động hay không.',
    'STm10001_08.245': 'Vậy lúc đó cô nghĩ tôi đã làm gì?',
    'STm10001_08.246': 'Rằng cô có thể là đồng bọn của đám buôn người. Hoặc có lẽ là... một kẻ trộm mộ.',
    'STm10001_08.250': 'Này, làm ơn đi, mở to mắt ra mà nhìn xem!==W== Tôi đáng yêu và duyên dáng nhường này, vậy mà cô nỡ nghĩ tôi là phường buôn người hay trộm mộ sao?',
    'STm10001_08.253': 'Ờ thì... Bởi vì lúc đó cô đang đứng cạnh một chiếc quan tài xa hoa đến dị thường, và nằm bên trong lại là một ==PLAYER_NAME== bất động không còn hơi thở.',
    'STm10001_08.261': 'Ừm, nghĩ lại thì cảnh tượng đó trông giống trộm mộ thật đấy. Hì hì.==W== Vậy nên cô mới tống cả tôi lẫn chiếc quan tài lên xe để làm bằng chứng cho "tội trạng" của Elis.',
    'STm10001_08.264': 'Đúng vậy. Tôi xin lỗi...',
    'STm10001_08.266': 'Không cần phải xin lỗi đâu. Trong tình cảnh đó, bất kỳ ai cũng sẽ nghĩ tôi chỉ là một cái xác không hồn thôi.',
    'STm10001_08.267': 'Thảo nào thái độ của cô sau đó lại thay đổi... Khi tôi "sống lại", và Elis đã tự mình đứng ra che chở cho tôi. Điều đó chứng tỏ cô ấy không thể nào là kẻ trộm mộ hay tay sai buôn người được.',
    'STm10001_08.269': 'Đúng vậy. Nhưng tôi vẫn hoài nghi về thân phận thực sự của hai người...==W== Thế nên tôi mới đưa hai người quay trở lại Filanis.',
    'STm10001_08.270': 'Và lý do là vì...?',
    'STm10001_08.271': 'Elis cư xử rất tự nhiên như một người hầu cận. Nhưng ngài, với tư cách là chủ nhân của cô ấy...==W== lại chẳng hề có lấy một chút dáng vẻ trịch thượng hay ngạo mạn nào. Và cách ngài đối xử với cô ấy chẳng giống với kẻ dưới chút nào. Nó giống như...==W== một người bạn hơn.',
    'STm10001_08.277': '(Tôi sẽ tiếp tục đóng vai người hầu cận của cậu.==W== Nhưng thật lòng đấy, làm ơn hãy tỏ ra nghiêm khắc với tôi hơn một chút đi. Thể hiện chút uy quyền giùm cái! Chẳng có ai đối xử với kẻ hầu người hạ dịu dàng như cậu đâu.)',
    'STm10001_08.280': 'Elis từng cảnh báo tôi về điều đó, nhưng tôi thật sự không làm nổi... Dù cố gắng đến đâu, tôi cũng chẳng thể đối xử với một con người bằng xương bằng thịt như một nô<r=object></r>lệ.',
    'STm10001_08.282': 'Thế nên tôi bắt đầu tự hỏi liệu có phải cả hai người đều là những người từng chịu cảnh giam cầm hay không. Thuộc tầng lớp cao cấp phục vụ các Chấp Chính Quan hay Bán Thần chẳng hạn.==W== Hai người đã cùng nhau trốn thoát, và việc giả làm chủ tớ chỉ là cách ngụy trang thuận tiện nhất mà thôi.',
    'STm10001_08.283': 'Hóa ra là vậy...==W== Cô đưa chúng tôi đến Filanis là để bảo vệ chúng tôi, và giúp chúng tôi bắt đầu một cuộc đời mới với những thân phận mới tại đây.',
    'STm10001_08.285': 'Đúng vậy. Nếu Chấp Chính Quan Olympia biết được hai người từng chịu cảnh áp bức, người nhất định sẽ trao trả tự do cho hai người.',
    'STm10001_08.288': 'Cô tốt bụng đến mức khiến người ta cảm thấy khó tin đấy.',
    'STm10001_08.289': 'Đấng bảo hộ Olympia của cô, người trị vì Filanis, có thể cấm người dân Filanis giam cầm người khác, nhưng điều đó đâu có nghĩa là cô phải rời khỏi thành phố để cứu người ngoài vùng hoang dã chứ? Làm vậy chẳng phải sẽ chuốc thêm rắc rối cho người sao?',
    'STm10001_08.290': 'Chấp Chính Quan Olympia luôn dạy rằng bất kỳ ai đặt chân đến Filanis đều phải được sống như một con người tự do. Người ủng hộ chúng tôi giải cứu những số phận bất hạnh bằng biện pháp hòa bình bất cứ khi nào có thể, và trừng trị thích đáng những kẻ trục lợi trên thân xác đồng loại.',
    'STm10001_08.291': 'Và hơn hết... bản thân tôi cũng từng nếm trải cảnh ngộ đó. Tôi thấu hiểu cảm giác bị đối xử như một món đồ vô tri là thế nào. Vậy nên tôi sẽ giúp đỡ hai người bằng mọi giá.',
    'STm10001_08.292': '... Tại sao sự bất công tàn nhẫn ấy lại tồn tại chứ? Sao con người ta không thể cùng nhau chung sống trong hòa bình?',
    'STm10001_08.296': 'Đương nhiên là vì...==W== Ai nấy đều có những ước vọng mà mình khao khát đạt được, và có những kẻ chỉ có thể thỏa mãn mong muốn của bản thân bằng cách hy sinh số phận của người khác.',
    'STm10001_08.297': 'Hừ, đừng tưởng ai cũng ngây thơ như hai<r=good people></r> kẻ ngốc các người. Cứ cả tin như thế thì có ngày mất mạng đấy.',
    'STm10001_08.298': 'Cảm ơn lời cảnh báo của cô.==W== Nhưng...==W== Sau khi hai người tìm cách trốn khỏi nhà tắm và bị Thánh Nữ Leita bắt gặp, tôi đã bắt đầu suy nghĩ lại về thân phận thực sự của hai người. Có lẽ hai người không phải là những kẻ trốn chạy tầm thường.',
    'STm10001_08.301': 'Elis, cô chính là vị Thánh Nữ đào tẩu đúng không? Còn ==PLAYER_NAME== là một quý tộc có địa vị, vì lý do nào đó mà đã chọn cách giúp đỡ cô.',
    'STm10001_08.302': 'Hả!? Cô đang nói nhăng nói cuội gì thế? Làm sao tôi có thể là Thánh Nữ được chứ?',
    'STm10001_08.305': 'Đoán chuẩn xác thật đấy. Không hổ danh là một Vệ Dạ Giả... Ngoại trừ một điều cô ấy không thể nào biết được là tôi đến từ một thế giới khác, thì mọi phán đoán của cô ấy về cơ bản đều trúng phóc.',
    'STm10001_08.306': 'Khi Thánh Nữ Leita cố gắng xác định danh tính của cô... Trông ngài ấy như thể đã nhận ra cô, và thậm chí còn cố tình ra tay bao che cho cô nữa.',
    'STm10001_08.313': 'Bình thường... Một người vô tội sẽ chẳng có lý do gì phải trốn chạy qua đường cống ngầm như thế cả. Nhưng khi phát hiện cô trốn dưới gầm xe ngựa, ngài ấy lại xua tay gạt đi bằng cách trêu chọc vài câu.',
    'STm10001_08.314': 'Thế nên tôi đã âm thầm điều tra...==W== Về quá khứ của Thánh Nữ Leita trước khi ngài ấy trở thành một Thánh Nữ thực thụ, và phát hiện ra ngài ấy từng học cùng khóa tu viện với vị Thánh Nữ đào tẩu kia.',
    'STm10001_08.316': 'Mọi người trong khóa tu viện năm đó đều có lý lịch rõ ràng, ngoại trừ vị Thánh Nữ đào tẩu nọ. Không một ai trong số họ có thể lưu lạc đến Filanis trong cảnh ngộ khốn cùng này,==W== điều đó chỉ để lại một khả năng duy nhất...',
    'STm10001_08.318': 'Dù tôi có quen biết vị Thánh Nữ đó đi chăng nữa thì điều ấy cũng chẳng chứng minh được gì cả...==W== Chúng tôi đâu nhất thiết phải gặp nhau trong đợt huấn luyện tu viện. Có khi chúng tôi chỉ là hàng xóm cũ ở Emor thì sao...==W== Đúng vậy, chỉ là hàng xóm thôi!',
    'STm10001_08.320': 'Làm sao một vị Thánh Nữ lại có thể làm hàng xóm với một người lưu lạc chứ? Nếu cô bảo ngài ấy là hàng xóm của ==PLAYER_NAME==, thì ở nhà tắm...==W== trông Thánh Nữ Leita hoàn toàn không nhận ra ==PLAYER_NAME== chút nào.',
    'STm10001_08.323': 'Tôi... chuyện đó tôi cũng có thể giải thích được mà...',
    'STm10001_08.324': 'Thôi nào Elis, đừng cố chống chế nữa.==W== Tôi nghĩ Alina nói ra những điều này không phải để tố giác chúng ta đâu. Xét cho cùng, cô ấy đâu hề nhắc lại những mối hoài nghi này trong suốt bài kiểm tra ở nhà tắm.',
    'STm10001_08.325': 'Chấp Chính Quan Olympia chưa từng ban hành lệnh truy nã vị Thánh Nữ đào tẩu tại Filanis. Đại nhân Coppelius cũng từng nói với tôi rằng ngài ấy không tin vị Thánh Nữ đào tẩu đã làm bất cứ điều gì sai trái.',
    'STm10001_08.326': 'Và trong suốt thời gian qua, ngay cả khi bị nhốt trên xe tù, hai người cũng chưa từng làm bất cứ điều gì nguy hiểm. Với tư cách là một Vệ Dạ Giả của Filanis, tôi không có bất kỳ lý do nào để bắt giữ Elis cả.',
    'STm10001_08.327': 'Dù vậy tôi nghĩ đó vẫn chưa phải là toàn bộ sự thật. Lúc ở trước lối vào nhà tắm công cộng...',
    'STm10001_08.329': 'Ngài có thể cho tôi biết về <color=#3faeae>ma pháp phục sinh</color> được không?',
    'STm10001_08.343': '<size=50>Cứ ra giá đi...==W== Tôi sẽ trao cho ngài bất cứ thứ gì tôi có!',
    'STm10001_08.348': 'T-==W==Thật sao...?==W== Tôi có thể hỏi ngài về tòa tháp và những lời ước nguyện được không?',
    'STm10001_08.352': 'Rõ ràng cô có điều gì đó muốn thỉnh giáo tôi.==W== Nếu thân phận của chúng tôi bị bại lộ, chúng tôi sẽ bị bắt giam hoặc buộc phải bỏ trốn.==W== Và khi đó cô sẽ chẳng bao giờ có được câu trả lời mà mình hằng tìm kiếm nữa, đúng chứ?',
    'STm10001_08.359': 'Thật đáng xấu hổ làm sao. Tôi đã may mắn được ban cho thân phận quý tộc, và dẫu mang danh hiệu "Hiệp Sĩ", thâm tâm tôi vẫn đầy rẫy những ham muốn ích kỷ.',
    'STm10001_08.361': '==PLAYER_NAME==, ngài nói đúng lắm. Tôi thực sự có toan tính riêng trong chuyện này.==W== Tôi thực lòng muốn... học hỏi tri thức ấy từ ngài.',
    'STm10001_08.362': 'Vì vậy xin ngài đừng nghĩ về tôi... như một người tốt vô tư lự chỉ đơn thuần muốn ra tay giúp đỡ hai người.',
    'STm10001_08.363': 'Ai mà chẳng có mong ước của riêng mình.==W== Miễn là những động cơ ấy không làm tổn hại đến người khác, tôi không nghĩ có điều gì sai trái cả.',
    'STm10001_08.364': 'Cô có muốn tiếp tục cuộc trò chuyện lúc trước không? Về tòa tháp và những lời ước nguyện ấy?',
    'STm10001_08.367': 'Vâng... Chỉ có các Thánh Nữ và Tế Ty mới được bước vào ngọn tháp của Filanis để dâng lời ước nguyện, nhưng một hiệp sĩ như tôi cũng có thể giành được cơ hội ngàn năm có một sau khi tích lũy đủ quân công.',
    'STm10001_08.368': 'Tôi muốn thực hiện một điều ước vì những người đồng đội của mình, nhưng tôi lại không biết... mình phải làm thế nào mới đem lại kết quả như ý muốn.',
    'STm10001_08.369': 'Thế nên tôi đã rất hy vọng có thể hỏi ngài xem việc ước nguyện thực sự diễn ra như thế nào.',
    'STm10001_08.372': 'Thực hiện một điều ước vì đồng đội của cô ư? Cả đời người cô chỉ có duy nhất một cơ hội thôi đấy. Cô không nên nghĩ cho bản thân mình một chút sao?',
    'STm10001_08.374': 'Tôi... Tôi nợ họ một ân tình quá lớn. Bằng mọi giá, tôi nhất định phải đền đáp cho họ.',
    'STm10001_08.379': 'Còn bao nhiêu cách khác để báo ân mà... Đây là một điều ước thần kỳ đấy. Một điều ước có thể hiện thực hóa mọi thứ trên đời!',
    'STm10001_08.384': 'Vâng... Nhưng tôi nghĩ đây là cách duy nhất tôi có thể đền đáp cho họ. Xin hãy đi theo tôi. Tôi sẽ dẫn hai người đến gặp họ.',
    'STm10001_08.393': 'Elis và tôi theo chân Alina bước ra ngoài qua cánh cửa sau của tòa nhà.',
    'STm10001_08.406': 'Chúng tôi băng qua khu rừng hơn mười phút. Chỉ đến khi ngay cả Cự Tháp của Filanis cũng đã khuất dạng sau những tán cây rậm rạp, Alina mới chịu dừng bước.',
    'STm10001_08.414': 'Đây chính là những người đồng đội mà tôi đã nhắc đến.',
    'STm10001_08.415': 'Đây là... một nghĩa trang sao? Xin lỗi nhé, chúng tôi không hề hay biết...',
    'STm10001_08.417': 'Không cần phải xin lỗi đâu. Lẽ ra tôi nên nói cho hai người biết sớm hơn mới phải.==W== Một năm trước, Vệ Dạ Giả Alina của Filanis hôm nay... vẫn còn là một đấu sĩ nơi đấu trường Emor.',
    'STm10001_08.420': 'Hả? Đấu sĩ ư? Kiểu ngôi sao lừng danh chiến đấu nơi Đại Đấu Trường và đắm mình trong tiếng reo hò của vạn người ấy sao?',
    'STm10001_08.422': 'Những đấu sĩ như thế quả thật có tồn tại. Nhưng thế giới hoa lệ ấy chẳng hề có chút liên can nào tới tôi cả.',
    'STm10001_08.423': 'Thuở ấy... tôi chẳng qua chỉ là một đấu sĩ khốn cùng, thậm chí đến cả một cái tên cũng chưa từng có...',

    # ==================== STm10001_09 (113 items) ====================
    'STm10001_09.4': 'Hồi Chín',
    'STm10001_09.5': 'Đấu Sĩ',
    'STm10001_09.6': 'Alina hé lộ quá khứ từng là một đấu sĩ. Cô đã giành lấy tự do sau khi đả bại những con rối ma pháp, nhưng lại không thể bảo vệ được những người đồng đội từng cùng chung hoạn nạn, và nỗi ân hận tột cùng ấy đã hóa thành ước nguyện của đời cô.',
    'STm10001_09.38': 'Đấu Sĩ Tiền Bối',
    'STm10001_09.41': 'Này, Số 18. Đến lượt nhóc rồi đấy.',
    'STm10001_09.46': 'Nghe cho kỹ đây. Càng đổ nhiều máu thì đám đông trên khán đài càng phát cuồng, nhất là khi đấu sĩ lại là một đứa con gái mảnh khảnh như nhóc. Chẳng cần biết đó là máu của nhóc hay của đối thủ... Bọn họ đều sẽ hò reo sung sướng cả thôi. Hiểu chưa?',
    'STm10001_09.51': 'Chà, nếu nhóc có thể chiến đấu để vang danh thiên hạ, thì nhóc có thể vĩnh viễn nói lời tạm biệt với cái xó xỉnh tồi tàn này.',
    'STm10001_09.53': 'Nhóc sẽ được sống trong một dinh thự ngát hương một dược và nhũ hương. Tựa mình trên những chiếc đệm lụa nhồi lông thiên nga bên hồ nước trong vắt, nhâm nhi rượu mật ong ướp lạnh như một vị tiểu thư đài các…',
    'STm10001_09.55': 'Haha! Đó mới gọi là sống chứ. Cá là nhóc cũng từng mơ về một cuộc đời như thế, đúng không?',
    'STm10001_09.64': '...Trời đất. "Vâng, vâng"... Nhóc chỉ biết nói mỗi từ đó thôi à? Nhóc là một con rối hay sao thế?',
    'STm10001_09.75': 'Hừ, thôi được rồi. Bỏ đi. Ra sân đi. Một kẻ yếu đuối với ánh mắt vô hồn như nhóc thì khéo vừa bước ra đã gục ngã rồi bị lôi xác ra ngoài ngay thôi.',
    'STm10001_09.90': 'Nơi trung tâm thành bang Emor sừng sững một nhà hát mà bức màn nhung chưa từng bao giờ hạ xuống.',
    'STm10001_09.98': 'Với những bức tường thành cao vút làm rèm che và bãi cát vàng làm sân khấu. Khán giả y phục lộng lẫy ngồi dưới ánh mặt trời rực rỡ, trong khi những người mang xiềng xích đứng ngơ ngác nơi góc khuất, chẳng bao giờ thấy được ánh sáng ban mai.',
    'STm10001_09.113': 'Người ta ca tụng Đại Đấu Trường là "trái tim bơm nguồn sống cho toàn bộ Emor".',
    'STm10001_09.116': 'Thế nhưng chưa bao giờ là vinh quang giữ cho trái tim ấy đập rộn rã... Mà chính là những giọt máu nhuộm đỏ bãi cát vàng.',
    'STm10001_09.122': 'Tôi sinh ra dưới chân những bức tường thành cao ngút ngàn ấy, và kế thừa xiềng xích của cha mẹ mà chưa từng có lấy một cái tên.',
    'STm10001_09.127': 'Chẳng một ai hỏi đứa trẻ nơi đây muốn trở thành ai khi lớn lên. Kể từ khoảnh khắc cất tiếng khóc chào đời, số phận đã định sẵn vai diễn cho chúng, gắn chặt những sợi dây điều khiển như những con rối.',
    'STm10001_09.132': 'Lựa chọn duy nhất mà tôi từng được phép đưa ra... chính là thứ vũ khí để chiến đấu. Và tôi đã chọn thanh kiếm.',
    'STm10001_09.141': 'Đấu trường được điều hành bởi hai Chấp Chính Quan song sinh. Người chị cho thuê địa điểm và võ sĩ, trong khi người em bán vé và chủ trì những trận quyết đấu được họ tô vẽ là "võ thuật đỉnh cao"...',
    'STm10001_09.148': 'Những kẻ đứng đầu sẽ thao túng đấu sĩ,==W== ép họ phải giãy giụa, gào thét,==W== rồi ngã xuống để làm vui lòng đám đông trên khán đài.',
    'STm10001_09.162': 'Đấu Sĩ Bị Thương',
    'STm10001_09.164': 'Ừm... Cảm ơn cậu vì lúc nãy đã nương tay với tớ nhé.',
    'STm10001_09.168': 'Bôi chút mật ong lên vết thương đi. Nó sẽ giúp vết thương không bị mưng mủ đấy.',
    'STm10001_09.171': 'T-Thật sao? À, tớ tên là Yonon... Tên cậu là gì thế?',
    'STm10001_09.172': 'Số 18.',
    'STm10001_09.176': 'Đấy là số hiệu của cậu mà, đúng không? Tớ cũng có số hiệu này—103. Nhưng tớ đâu có hỏi số hiệu của cậu đâu…',
    'STm10001_09.180': 'Tôi không có tên, và tôi cũng chẳng cần có tên làm gì.',
    'STm10001_09.181': 'Đấu Sĩ Trẻ Tuổi',
    'STm10001_09.183': 'Thôi nào Yonon. Lại đây mau để tớ băng bó vết thương cho cậu.',
    'STm10001_09.184': 'Đấu Sĩ Chút Danh Tiếng',
    'STm10001_09.186': 'Yonon, cậu có chắc là an toàn khi nói chuyện với con nhỏ đó không? Ai mà biết trong đầu nó đang toan tính điều gì chứ? Tốt nhất là nên tránh xa nó ra kẻo có ngày bị đâm sau lưng đấy...',
    'STm10001_09.192': 'Đâm sau lưng ư? Nhưng cô ấy là một người tốt bụng mà...==W== Tớ không nghĩ cô ấy lại hại tớ đâu…',
    'STm10001_09.196': 'Đấu sĩ nơi đây không có những cái tên đàng hoàng như những khán giả ngồi trên khán đài.',
    'STm10001_09.204': 'Tất nhiên, cũng có một vài đấu sĩ tự đặt biệt danh cho mình dựa trên phong cách chiến đấu, với hy vọng đám đông sẽ ghi nhớ đến họ...',
    'STm10001_09.206': 'Dẫu vậy, tôi chưa từng nghĩ đến việc tự đặt cho mình một cái tên. Xét cho cùng, chúng tôi chỉ là những món đồ, là tài sản của chủ nhân.',
    'STm10001_09.208': 'Đối với một đấu sĩ, một "cái tên" chẳng qua chỉ là một tấm biển báo giá, một thứ để nâng giá trị của bạn lên trên thị trường mà thôi.',
    'STm10001_09.212': 'Tôi thà mài giũa kiếm thuật của mình còn hơn lãng phí thời gian vào những điều phù phiếm đó.',
    'STm10001_09.215': 'Mỗi khi tôi đánh gục một đối thủ trên sàn đấu, đám đông lại siết chặt nắm tay, giơ ngón cái lên và thúc giục tôi kết liễu trận đấu bằng một đòn chí mạng.',
    'STm10001_09.228': 'Thế nhưng... tôi chẳng hề có hứng thú nghe theo mệnh lệnh của họ, càng không bao giờ muốn ra tay tước đoạt mạng sống của ai chỉ để làm vui lòng kẻ khác.',
    'STm10001_09.231': 'Vậy nên trong các trận đấu của mình, tôi chỉ dùng mũi kiếm rạch nhẹ lên da đối thủ, khéo léo tránh đi mọi mạch máu lớn và gân cơ hiểm yếu.',
    'STm10001_09.239': 'Bằng cách đó, máu trông có vẻ tuôn ra rất nhiều, nhưng chẳng một ai phải mất đi tính mạng cả.',
    'STm10001_09.246': 'Thế nhưng tôi đâu hay biết rằng... Nơi đấu trường không lối thoát ấy, mọi niềm hy vọng nhỏ nhoi chỉ dẫn đến nỗi tuyệt vọng tàn khốc hơn mà thôi...',
    'STm10001_09.249': 'Một năm trước,==W== Chấp Chính Quan của Filanis đã đến đây cùng một lô rối ma pháp khổng lồ. Vị tiểu thư nhân hậu ấy ôm ấp ý định dùng những con rối này để thay thế cho con người.',
    'STm10001_09.251': 'Nhưng người đâu biết rằng, đám khán giả kia chẳng hề bận tâm đến kỹ năng hay sự phô diễn võ thuật. Thứ mà chúng khao khát đến điên cuồng chính là nhìn thấy máu thịt của những sinh linh bằng xương bằng thịt rơi xuống.',
    'STm10001_09.267': 'Để đón chào Chấp Chính Quan Filanis, hai vị Chấp Chính Quan cai quản đấu trường đã dựng nên một trận huyết chiến quy mô lớn: một cuộc quyết đấu sinh tử giữa đấu sĩ và những con rối ma pháp.',
    'STm10001_09.269': 'Thế nhưng đó chưa bao giờ là sân khấu để thử nghiệm năng lực của những con rối. Đó thực chất là một cuộc thanh trừng để lũ rối ma pháp trừ khử những "con rối cũ" đã không còn chịu phục tùng chủ nhân vô điều kiện.',
    'STm10001_09.279': 'Số 18, cầm lấy này. Cái này dành cho cậu đấy.',
    'STm10001_09.281': 'Yonon? Đây là... một thanh kiếm sao?',
    'STm10001_09.289': 'Ừm. Chúng ta sắp phải chiến đấu với những con rối ma pháp rồi, đúng không?',
    'STm10001_09.291': 'Kiếm của cậu đã mẻ và cùn cả rồi... Bọn tớ đã gom góp số tiền ít ỏi của mọi người lại để mua cho cậu một thanh kiếm mới.',
    'STm10001_09.293': 'Dành cho tôi...? Tại sao chứ?',
    'STm10001_09.296': 'Ừm... Xem như là lời cảm ơn vì cậu đã luôn giúp đỡ bọn tớ đi? Ahaha... Nếu không nhờ có cậu nương tay, có lẽ tất cả bọn tớ đã chẳng còn sống sót đến tận bây giờ.',
    'STm10001_09.300': 'D-Dù sao thì thanh kiếm giờ là của cậu rồi nhé. Hì hì… Chúc cậu may mắn trong trận chiến sắp tới. Nếu có ai có thể đánh bại được lũ rối ma pháp đó, thì người đó chỉ có thể là cậu thôi, Số 18. Mọi người đều trông cậy vào cậu đấy.',
    'STm10001_09.304': 'À, tất nhiên bọn tớ cũng sẽ cố hết sức mình. Nhưng lũ rối ma pháp đó chắc chắn sẽ không nương tay như cậu đâu, nên tớ thấy hơi lo lo...',
    'STm10001_09.306': 'Tôi đã đắn đo không biết có nên nói cho cô ấy biết hay không, rằng tôi chiến đấu không vì bất kỳ ai cả, mà tôi chỉ đang giãy giụa chống lại số phận nghiệt ngã mà đấu trường đã áp đặt lên đời mình.',
    'STm10001_09.309': 'Thế nhưng... sức nặng của thanh kiếm trên tay đã chạm đến tận đáy lòng tôi, khiến tôi nghẹn ngào chẳng nói nên lời. Đó là món quà đầu tiên mà tôi nhận được trong suốt cuộc đời mình.',
    'STm10001_09.313': '<color=#bd3059><size=75>Không phải một phần thưởng, mà là một món quà thực sự...</color>',
    'STm10001_09.315': 'Vài ngày sau, chủ nhân đấu trường đã đẩy những người==RT==mà tôi từng cứu mạng, với những vết thương còn chưa kịp lành da,==RT==vào trận chiến khốc liệt chống lại lũ rối ma pháp.',
    'STm10001_09.321': 'Trận chiến bắt đầu vào thời khắc nửa đêm linh thiêng. Đấu trường vĩ đại thắp sáng hơn một ngàn đống lửa lớn cho màn biểu diễn hoành tráng.',
    'STm10001_09.323': 'Ban đầu, những con rối chỉ di chuyển vụng về cứng nhắc, và dường như hoàn toàn bất lực trước sự phối hợp ăn ý của chúng tôi.',
    'STm10001_09.343': 'Thế nhưng, cơ thể được cường hóa bằng ma pháp cùng khả năng mô phỏng quái đản đã biến chúng thành những đối thủ đáng sợ hơn chúng tôi tưởng tượng rất nhiều.',
    'STm10001_09.349': 'Lũ rối nhanh chóng học hỏi kiếm chiêu và chiến thuật của chúng tôi... rồi xoay chuyển hoàn toàn cục diện trận đấu. Những người đồng đội vốn đã mang thương tích của tôi lần lượt gục ngã.',
    'STm10001_09.355': 'Máu bắn tung tóe xèo xèo dữ dội trên những đống lửa than hồng... Nhưng ngay cả thanh âm ai oán ấy cũng bị vùi lấp dưới tiếng reo hò gầm rú cuồng loạn của khán giả.',
    'STm10001_09.357': 'Những ánh mắt khát máu của đám đông vào thời khắc ấy còn ghê rợn và đáng sợ hơn cả bầy rối ma pháp vô tri kia gấp bội phần.',
    'STm10001_09.360': 'May mắn thay, thứ mà lũ rối đã sao chép chính là kiếm thuật của tôi. Nhờ vậy mà những đồng đội ngã xuống không phải chịu những vết thương chí mạng. Đồng thời, tôi cũng nhìn ra cơ hội chiến thắng ẩn sau sự mô phỏng của chúng.',
    'STm10001_09.364': '_NOT_IN_LOG_==Off==<margin-left=5em><align=left><size=90>Lũ rối không biết đau đớn kia...==RT====RT====RT====RT====A0.8==',
    'STm10001_09.366': '_NOT_IN_LOG_==Off==<margin-right=5em><align=right><size=90><color=black>Đến lúc dứt điểm rồi.==RT====RT====A0.8==',
    'STm10001_09.368': '_NOT_IN_LOG_==Off==<size=90>==RT====RT====RT==Để xem ma lực của các ngươi cạn kiệt trước...==RT====A0.8==',
    'STm10001_09.370': '_NOT_IN_LOG_==Off==<color=#bd3059><size=120>... hay kiếm của ta sẽ gãy vụn trước!!==A0.8==',
    'STm10001_09.372': '<color=#bd3059>==Off==Lũ rối không biết đau đớn kia... Đến lúc dứt điểm rồi.==RT==Để xem ma lực của các ngươi cạn kiệt trước hay kiếm của ta sẽ gãy vụn trước!!',
    'STm10001_09.379': 'Tôi đã gắng gượng chống đỡ đến phút cuối cùng bằng cách nào...==W== Bản thân tôi cũng chẳng còn nhớ rõ nữa.',
    'STm10001_09.384': 'Cuối cùng, khi ánh bình minh ló dạng, giữa những tiếng reo hò rung chuyển cả đấu trường, tôi ngã quỵ bên cạnh con rối cuối cùng xuống bãi cát đẫm máu.',
    'STm10001_09.394': 'Và... khi tôi tỉnh lại lần nữa, tôi đã thấy mình đang ở trên một cỗ xe ngựa hướng về Filanis.==W== Chấp Chính Quan Olympia của Filanis đã chuộc tôi ra, trao trả tự do và phong cho tôi tước vị Hiệp Sĩ.',
    'STm10001_09.402': 'Chấp Chính Quan Olympia nói với tôi rằng người sẽ đẩy mạnh nghiên cứu về rối ma pháp để thay thế con người, và một ngày nào đó sẽ trả lại tự do cho tất cả những ai chịu cảnh áp bức.',
    'STm10001_09.405': 'Đó cũng là khoảnh khắc cái tên "Alina Colossi" chính thức được sinh ra trên thế gian này.',
    'STm10001_09.407': 'Để đền đáp ơn sâu của Chấp Chính Quan Olympia, tôi đã gia nhập Đội Vệ Dạ của Filanis. Và tôi thề sẽ dốc trọn sinh mệnh bảo vệ thành phố hoàn mỹ mà người đã gây dựng nên—một thành phố không có bóng dáng của sự bất công.',
    'STm10001_09.409': 'Khi tôi gia nhập Đội Vệ Dạ, Chấp Chính Quan Olympia thậm chí đã trả trước cho tôi mười năm tiền lương... Cả đời sống trong cảnh khốn cùng, tôi hoàn toàn chẳng biết phải dùng số tiền lớn ấy vào việc gì.',
    'STm10001_09.411': 'Vậy nên tôi đã mang theo một túi tiền vàng lớn quay trở lại Emor. Tôi muốn chuộc lại tự do cho những người đồng đội bị thương của mình.',
    'STm10001_09.415': 'Cũng như tôi đã vượt qua đêm trường tăm tối để đón chào bình minh rạng rỡ, tôi muốn những người bạn của mình cũng được nhìn thấy ánh sáng diệu kỳ ấy.',
    'STm10001_09.421': 'Chủ Nô Đấu Trường',
    'STm10001_09.423': 'Yonon ư? Xin lỗi nhé, ta chưa từng nghe thấy cái tên đó bao giờ.',
    'STm10001_09.427': '...Ồ, khoan đã nào. Hình như đứa mang số 103 đợt trước đúng là có xưng cái tên đó thì phải...',
    'STm10001_09.432': 'Đợt trước ư? Ý ông là sao?',
    'STm10001_09.435': 'Thì đúng như lời ta nói đấy. Những kẻ bỏ mạng trong Đấu Trường thì số hiệu của chúng sẽ được chuyển lại cho người khác, đúng chứ? Tất cả những đứa tham gia trận đánh với lũ rối đợt đó đều chết sạch cả rồi. Đương nhiên là toàn bộ số hiệu của chúng đều được gán cho người mới rồi.',
    'STm10001_09.439': 'Đ-Đừng có nói dối tôi...! Những con rối đó không thể nào giết hại ai được!',
    'STm10001_09.445': 'Ớ-Ớ kìa, quý cô Hiệp Sĩ xin hãy bớt giận...! Ta đâu có rảnh rỗi mà đi lừa cô làm gì, đúng không nào?',
    'STm10001_09.449': 'Phần lớn những đứa tham chiến trong trận đó vốn dĩ đã bị thương nặng sẵn rồi, mà đấu trường thì đâu có rỗi hơi đi nuôi báo cô lũ tàn phế... Có đứa cầm cự được nửa ngày... Đứa nào dai sức nhất thì sống thêm được vài ba hôm... Chỉ có thế thôi.',
    'STm10001_09.451': 'Có vài đứa chỉ bị thương nhẹ, nhưng... Chúng lại bị tống thẳng vào sàn đấu tiếp, bao gồm cả con nhóc 103 kia. Nghe đâu là để làm bia thử nghiệm chiêu thức mới cho lũ rối ma pháp.',
    'STm10001_09.459': 'Dù sao đi nữa, hiện tại ta có thể tìm cho cô những người có phẩm chất tốt hơn bọn chúng nhiều. Còn nếu cô muốn tìm vật kỷ niệm của trận đấu năm đó, thì ta vẫn còn giữ thẻ bài số hiệu của hai đứa... Hề hề, cô mua một người đi rồi ta tặng kèm luôn cho.',
    'STm10001_09.464': 'Tấm thẻ bài số hiệu quen thuộc trượt khỏi kẽ tay tôi, rơi xuống vũng máu dưới chân đấu trường vốn chẳng bao giờ khô cạn.',
    'STm10001_09.468': '==Off==<color=black>Lũ rối ma pháp quả thực đã bước lên sân khấu của đấu trường...==RT==Thế nhưng chúng chưa từng cứu rỗi được bất kỳ ai.',
    'STm10001_09.472': 'Tôi xin lỗi... Tôi đã quay trở lại quá muộn màng...',
    'STm10001_09.474': 'Tôi xin lỗi... Lẽ ra chúng ta đã phải cùng nhau giành lấy chiến thắng rồi mới phải...',
    'STm10001_09.476': 'Tôi xin lỗi... Tôi đã không thể cứu được một ai trong số các bạn...',
    'STm10001_09.480': 'Giữa những đợt reo hò đinh tai nhức óc dội lại từ đấu trường, tôi lê bước vô định qua từng góc phố tiêu điều của Emor.',
    'STm10001_09.482': 'Màn biểu diễn được ưa chuộng nhất hiện nay là cho người đối đầu với lũ rối ma pháp thay vì quyết đấu với nhau. Đó chỉ là một cuộc tàn sát một chiều, thỏa mãn thị hiếu man rợ của đám khán giả.',
    'STm10001_09.486': 'Và tất cả những điều đó xảy ra chỉ vì... chính tôi đã chứng minh trong trận đấu định mệnh ấy rằng con người có thể cầm cự được trước lũ rối ma pháp...',
    'STm10001_09.488': 'Tôi... Chính đôi tay tôi đã vô tình tước đoạt đi con đường sống của tất cả mọi người...',
    'STm10001_09.490': '... Không, vẫn chưa. Mọi chuyện vẫn chưa thể kết thúc như thế này được. Không thể nào.',
    'STm10001_09.499': 'Chính vào khoảnh khắc tuyệt vọng ấy, tôi chợt nhớ lại câu chuyện về tòa tháp mà Yonon từng nhắc đến năm nào.',
    'STm10001_09.504': 'Này Số 18, cậu có biết không?! Người ta bảo rằng nếu bước chân vào ngọn tháp đó và thành tâm dâng lời ước nguyện, thì mọi điều ước đều sẽ trở thành hiện thực đấy!',
    'STm10001_09.506': 'Hừm… "Cầu xin người đừng để kiếp sau con lại phải sinh ra trong cảnh khổ cực nữa..." Cậu nghĩ ước như thế liệu có linh nghiệm không?',
    'STm10001_09.511': 'Nghĩ ngợi chuyện đó làm gì cho mệt. Nơi đó chỉ dành riêng cho các Nguyên Lão, Tế Ty và Thánh Nữ thôi. Những người thấp cổ bé họng như chúng ta làm gì có cửa bước chân vào.',
    'STm10001_09.513': 'Tớ biết chứ, tớ biết mà. Mơ mộng một chút thì có hại gì đâu nào. Nếu chúng mình cùng sống sót qua kiếp nạn này, biết đâu một ngày nào đó ai trong chúng ta sẽ gặp may mắn thì sao?',
    'STm10001_09.515': 'Và nếu một người trong số chúng ta thực sự bước chân được vào ngọn tháp đó... Người ấy có thể thay mặt tất cả dâng lời nguyện ước! "Xin đừng để bất kỳ ai trong chúng tôi phải chịu khổ cực ở kiếp sau nữa"!',
    'STm10001_09.520': 'Nếu tiền vàng không thể đem các bạn quay trở lại... Tôi sẵn sàng dâng hiến bất cứ thứ gì quý giá hơn cả vàng ròng. Tôi sẽ làm mọi giá.',
    'STm10001_09.522': 'Nếu cái chết đã cướp các bạn đi, tôi sẽ bước chân vào ngọn tháp ấy để dâng lời ước nguyện. Chính tôi sẽ tự tay đưa mọi người quay trở về.',
    'STm10001_09.525': 'Cầm thanh kiếm mà các bạn trao tặng trên tay, tôi xin thề... Tôi sẽ không ngừng lập nên chiến công cho đến khi giành được quyền bước chân vào ngọn tháp thiêng liêng ấy.',
    'STm10001_09.527': 'Bãi cát đẫm máu kia tuyệt đối không thể là nơi câu chuyện của các bạn khép lại.',
    'STm10001_09.531': 'Đó chính là cách mà Số 18, một người từng nếm trải bao cay đắng,==W== đã trở thành Alina, một Vệ Dạ Giả kiên cường.',
    'STm10001_09.537': 'Số 18 năm xưa từng cầm kiếm lên chiến đấu chỉ đơn thuần là để tìm kiếm con đường sống.',
    'STm10001_09.543': 'Thế nhưng đó không còn là lý do duy nhất mà "Alina" ngày hôm nay vung thanh kiếm này nữa. Tôi muốn được gặp lại tất cả mọi người một lần nữa... Để có thể nói một lời xin lỗi trọn vẹn.',
    'STm10001_09.550': 'Để nói với họ rằng tôi thực sự xin lỗi vì đã phụ lòng tin yêu của họ... Vì đã không thể ở bên cạnh họ khi họ đau đớn khổ sở nhất. Tôi thực sự... vô cùng xin lỗi.',
}
